import re, pathlib
p = pathlib.Path('app/models/account/data_transfer/record_set.rb')
src = p.read_text()
src = src.replace('''  attr_reader :account, :model, :attributes

  def initialize(account:, model:, attributes: nil)
    @account = account
    @model = model
    @attributes = (attributes || model.column_names).map(&:to_s)
  end
''', '''  attr_reader :account, :model, :attributes

  def initialize(account:, model:, attributes: nil, filter: nil)
    @account = account
    @model = model
    @attributes = (attributes || model.column_names).map(&:to_s)
    @filter = filter
  end
''')
src = src.replace('''    def records
      model.where(account_id: account.id)
    end
''', '''    def records
      apply_filter model.where(account_id: account.id)
    end

    def apply_filter(relation)
      @filter.present? ? @filter.call(relation) : relation
    end
''')
p.write_text(src)
PY
