class ZipFile::Writer
  attr_reader :byte_size

  def initialize(io = nil)
    @entries = []
    @byte_size = 0
    @output_io = io ? CountingIO.new(io, self) : nil
    @streamer = nil
    @digest = Digest::MD5.new
  end

  def stream_to(io)
    @output_io = CountingIO.new(io, self)
    @streamer = nil
    @digest = Digest::MD5.new
    @byte_size = 0
  end

  def write(data)
    raise "No output stream configured" unless @output_io

    @output_io.write(data)
    data.bytesize
  end

  def add_file(path, content = nil, compress: true)
    @entries << path
    write_method = compress ? :write_deflated_file : :write_stored_file

    if block_given?
      streamer.public_send(write_method, path) { |sink| yield sink }
    else
      streamer.public_send(write_method, path) { |sink| sink.write(content) }
    end
  end

  def glob(pattern)
    @entries.select { |e| File.fnmatch(pattern, e) }.sort
  end

  def exists?(path)
    @entries.include?(path)
  end

  def close
    streamer.close
  end

  def checksum
    Base64.strict_encode64(@digest.digest)
  end

  # Counts bytes and updates the checksum for every write which flows through
  # ZipKit. This lets the S3 upload path know the finished archive's size and
  # checksum without buffering it.
  class CountingIO
    def initialize(io, writer)
      @io = io
      @writer = writer
    end

    def write(data)
      count(data)
      @io.write(data)
    end

    def <<(data)
      count(data)
      @io << data
    end

    def method_missing(name, *args, &block)
      @io.public_send(name, *args, &block)
    end

    def respond_to_missing?(name, include_private = false)
      @io.respond_to?(name, include_private) || super
    end

    private
      def count(data)
        @writer.instance_variable_set(:@byte_size, @writer.byte_size + data.bytesize)
        @writer.instance_variable_get(:@digest).update(data)
      end
  end

  private
    def streamer
      @streamer ||= ZipKit::Streamer.new(@output_io)
    end
end
